// prepareRelease() must finalize every derived file BEFORE it commits, so the released commit
// is self-consistent (#889).
//
// Two symptoms, one root cause: `cut` committed generated files with no prettier/gen pass,
// so (1) the committed CHANGELOG.md failed the repo-wide `prettier --check .` and turned
// main red after every release, and (2) extension/src/data/appChangelogs.ts — the per-app
// version data the extension imports — was left stale, so the tag declared app versions its
// own committed data did not match. Each needed a manual fixup commit after the tag. This
// test walks a real release over a fixture history and asserts neither can recur.
//
// Every one of these now runs on a BRANCH, because `prepareRelease` refuses to run on `main`
// (#1208). That is not test scaffolding working around a guard — it is the guard, exercised.
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { mkdirSync, writeFileSync, readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import prettier from 'prettier';
import { prepareRelease, tagRelease, release } from '../dist/release.js';
import { newRepo } from './fixture.js';

/** The root files every release reads: a changelog to append to, and a manifest to match. */
function seedRoot(repo, version = '0.6.0') {
  writeFileSync(join(repo.dir, 'CHANGELOG.md'), '# Changelog\n\nIntro.\n\n<!-- releases below; newest first -->\n');
  mkdirSync(join(repo.dir, 'extension', 'src', 'data'), { recursive: true });
  writeFileSync(join(repo.dir, 'extension', 'manifest.json'), JSON.stringify({ version }));
}

describe('prepareRelease() finalizes every derived file before it commits (#889)', () => {
  test('the CHANGELOG.md it writes is already prettier-clean, and appChangelogs.ts is regenerated', async () => {
    const repo = newRepo();
    try {
      // A repo-shaped fixture: one app with a changelog, plus the root changelog + manifest
      // the release itself needs.
      repo.commit('scaffold notaboard', 'extension/src/apps/notaboard/index.ts');
      writeFileSync(
        join(repo.dir, 'extension', 'src', 'apps', 'notaboard', 'CHANGELOG.md'),
        '# Changelog\n\n## 1.0.0 — 2026-05-01\n\n- Initial release.\n',
      );
      writeFileSync(join(repo.dir, 'CHANGELOG.md'), '# Changelog\n\nIntro.\n\n<!-- releases below; newest first -->\n');
      mkdirSync(join(repo.dir, 'extension', 'src', 'data'), { recursive: true });
      writeFileSync(join(repo.dir, 'extension', 'manifest.json'), JSON.stringify({ version: '0.6.0' }));
      repo.git('add -A');
      repo.git('commit -q -m seed');
      repo.tag('v0.5.0');

      // A feat PR -> generateNotes emits `### New` immediately followed by a list, which is
      // exactly the shape prettier reformats (it wants a blank line after the heading, and no
      // trailing blank line). Before the fix, the committed CHANGELOG.md failed
      // `prettier --check .` on every single release.
      repo.mergePR(1, 'feat(notaboard): infinite canvas', 'extension/src/apps/notaboard/index.ts');
      repo.git('checkout -q -b main_chore_release_0.6.0');

      // `yes` skips the prompt. Nothing is caught: prepare neither pushes nor tags, so it has
      // no reason to fail here, and swallowing a rejection would hide one that matters.
      await prepareRelease('0.6.0', { root: repo.dir, yes: true });

      // Symptom 1: the committed root CHANGELOG.md is already prettier-clean.
      const clPath = join(repo.dir, 'CHANGELOG.md');
      const md = readFileSync(clPath, 'utf8');
      const config = await prettier.resolveConfig(clPath);
      const formatted = await prettier.format(md, { ...config, filepath: clPath });
      assert.equal(md, formatted, 'the committed CHANGELOG.md must already pass prettier --check');
      assert.match(md, /## v0\.6\.0/, 'and it actually recorded the release');

      // Symptom 2: appChangelogs.ts was regenerated from the bumped changelogs, not left stale.
      const appCl = join(repo.dir, 'extension', 'src', 'data', 'appChangelogs.ts');
      assert.ok(existsSync(appCl), 'appChangelogs.ts must be (re)generated by the release');
      const src = readFileSync(appCl, 'utf8');
      assert.match(src, /\bnotaboard:/, "it carries the app's data");
      assert.match(src, /version: "1\.1\.0"/, 'reflecting the bump this release just made');

      // The whole point: after the finalize, the working tree the release committed is clean —
      // nothing left for a manual fixup commit.
      assert.equal(repo.git('status --porcelain').trim(), '', 'the release commit leaves a clean tree');
    } finally {
      repo.cleanup();
    }
  });
});

// The same class of bug, one file further on (#1203).
//
// The lockfile records every workspace's version too, and the release bumped the deployables'
// package.json without re-resolving it — so v1.0.1 landed with four workspaces disagreeing
// with their own lockfile entries, and the Makefile job's sync guard failed on main for
// everyone. Because the release commits, pushes AND tags in one breath, the tagged tree was
// the broken one and only a commit on top of the tag could fix it.
//
// This walks a real release over a real npm workspace and asserts the committed lockfile
// agrees with the package.json the release just wrote.
describe('prepareRelease() refreshes the lockfile it just invalidated (#1203)', () => {
  test('the committed package-lock.json records the version the release wrote', async () => {
    const repo = newRepo();
    try {
      // A minimal but genuine npm workspace, so `npm install --package-lock-only` has
      // something real to re-resolve — no dependencies, so it resolves offline.
      mkdirSync(join(repo.dir, 'www'), { recursive: true });
      writeFileSync(
        join(repo.dir, 'package.json'),
        JSON.stringify({ name: 'root', private: true, workspaces: ['www'] }, null, 2) + '\n',
      );
      writeFileSync(
        join(repo.dir, 'www', 'package.json'),
        JSON.stringify({ name: '@kimtos/www', version: '1.0.0' }, null, 2) + '\n',
      );
      writeFileSync(
        join(repo.dir, 'www', 'CHANGELOG.md'),
        '# Changelog\n\n## 1.0.0 — 2026-05-01\n\n- Initial release.\n',
      );
      // Deliberately stale, the way a release leaves it: the lockfile still says the old
      // version after package.json has moved on.
      writeFileSync(
        join(repo.dir, 'package-lock.json'),
        JSON.stringify(
          {
            name: 'root',
            lockfileVersion: 3,
            requires: true,
            packages: {
              '': { name: 'root', workspaces: ['www'] },
              'node_modules/@kimtos/www': { resolved: 'www', link: true },
              www: { name: '@kimtos/www', version: '1.0.0' },
            },
          },
          null,
          2,
        ) + '\n',
      );
      writeFileSync(join(repo.dir, 'CHANGELOG.md'), '# Changelog\n\nIntro.\n\n<!-- releases below; newest first -->\n');
      mkdirSync(join(repo.dir, 'extension', 'src', 'data'), { recursive: true });
      writeFileSync(join(repo.dir, 'extension', 'manifest.json'), JSON.stringify({ version: '0.6.0' }));
      repo.git('add -A');
      repo.git('commit -q -m seed');
      repo.tag('v0.5.0');

      // A PR against www/ — so the release bumps that deployable's package.json, which is
      // exactly what leaves the lockfile behind.
      repo.mergePR(1, 'feat(www): a new pricing page', 'www/pages/pricing.vue');
      repo.git('checkout -q -b main_chore_release_0.6.0');

      await prepareRelease('0.6.0', { root: repo.dir, yes: true });

      const pkg = JSON.parse(readFileSync(join(repo.dir, 'www', 'package.json'), 'utf8'));
      const lock = JSON.parse(readFileSync(join(repo.dir, 'package-lock.json'), 'utf8'));
      assert.equal(pkg.version, '1.1.0', 'the release must have bumped the deployable at all');
      assert.equal(
        lock.packages.www.version,
        pkg.version,
        'the lockfile must record the version the release just wrote — otherwise the tagged tree is red',
      );

      // And it is IN the commit, not merely on disk: a refreshed lockfile the release did not
      // stage is the same red main, one step later.
      assert.equal(repo.git('status --porcelain').trim(), '', 'the release commit leaves a clean tree');
    } finally {
      repo.cleanup();
    }
  });

  // A dry run says "nothing written". The lockfile refresh shells out to npm and rewrites a
  // real file, so it is the one finalize step that could make that a lie — and the promise is
  // only kept by an early return several dozen lines above it, which is exactly the kind of
  // thing a later edit moves.
  test('a dry run does not touch the lockfile', async () => {
    const repo = newRepo();
    try {
      mkdirSync(join(repo.dir, 'www'), { recursive: true });
      writeFileSync(
        join(repo.dir, 'package.json'),
        JSON.stringify({ name: 'root', private: true, workspaces: ['www'] }, null, 2) + '\n',
      );
      writeFileSync(
        join(repo.dir, 'www', 'package.json'),
        JSON.stringify({ name: '@kimtos/www', version: '1.0.0' }, null, 2) + '\n',
      );
      writeFileSync(
        join(repo.dir, 'www', 'CHANGELOG.md'),
        '# Changelog\n\n## 1.0.0 — 2026-05-01\n\n- Initial release.\n',
      );
      // Deliberately STALE relative to www/package.json (1.0.0), so any refresh at all — even
      // one that ran before the bump — rewrites this file and the assertion below sees it. With
      // an already-correct lockfile the refresh is a no-op and this test would prove nothing.
      const lockPath = join(repo.dir, 'package-lock.json');
      const before =
        JSON.stringify(
          {
            name: 'root',
            lockfileVersion: 3,
            requires: true,
            packages: {
              '': { name: 'root', workspaces: ['www'] },
              'node_modules/@kimtos/www': { resolved: 'www', link: true },
              www: { name: '@kimtos/www', version: '0.9.0' },
            },
          },
          null,
          2,
        ) + '\n';
      writeFileSync(lockPath, before);
      writeFileSync(join(repo.dir, 'CHANGELOG.md'), '# Changelog\n\nIntro.\n\n<!-- releases below; newest first -->\n');
      mkdirSync(join(repo.dir, 'extension', 'src', 'data'), { recursive: true });
      writeFileSync(join(repo.dir, 'extension', 'manifest.json'), JSON.stringify({ version: '0.6.0' }));
      repo.git('add -A');
      repo.git('commit -q -m seed');
      repo.tag('v0.5.0');
      repo.mergePR(1, 'feat(www): a new pricing page', 'www/pages/pricing.vue');
      repo.git('checkout -q -b main_chore_release_0.6.0');

      await prepareRelease('0.6.0', { root: repo.dir, yes: true, dryRun: true });

      assert.equal(readFileSync(lockPath, 'utf8'), before, 'a dry run must leave package-lock.json byte-identical');
      assert.equal(repo.git('status --porcelain').trim(), '', 'and must write nothing at all');
    } finally {
      repo.cleanup();
    }
  });
});

// The split itself (#1208).
//
// `release()` used to write the changelogs, commit, push `main`, tag and push the tag in one
// call. That push was the only place in the project where content reached the deploy branch
// without a pull request, and because the notes and the tag were one step, a bad changelog was
// discovered on a tag that already existed — against a store version history that only ever
// goes forwards.
//
// Two functions now, and each refuses to do the other's job. These tests are the enforcement:
// a guard nothing exercises is a comment.
describe('a release is two commands, and neither does the other half (#1208)', () => {
  /** A repo mid-release: seeded, tagged v0.5.0, one merged PR, `origin` wired up. */
  function readyToRelease() {
    const repo = newRepo();
    const remote = repo.addRemote();
    repo.commit('scaffold notaboard', 'extension/src/apps/notaboard/index.ts');
    seedRoot(repo);
    writeFileSync(
      join(repo.dir, 'extension', 'src', 'apps', 'notaboard', 'CHANGELOG.md'),
      '# Changelog\n\n## 1.0.0 — 2026-05-01\n\n- Initial release.\n',
    );
    repo.git('add -A');
    repo.git('commit -q -m seed');
    repo.tag('v0.5.0');
    repo.mergePR(1, 'feat(notaboard): infinite canvas', 'extension/src/apps/notaboard/index.ts');
    repo.git('push -q origin main');
    return { repo, remote };
  }

  test('prepare refuses to run on main, and names the branch to create', async () => {
    const { repo } = readyToRelease();
    try {
      await assert.rejects(
        () => prepareRelease('0.6.0', { root: repo.dir, yes: true }),
        /refusing to prepare a release on main/,
        'the whole point of the split is that this cannot be done',
      );
      // And it refused BEFORE writing anything — a guard that fires after the damage is a report.
      assert.equal(repo.git('status --porcelain').trim(), '', 'it must not have written a thing');
    } finally {
      repo.cleanup();
    }
  });

  test('prepare refuses on main even as a dry run', async () => {
    const { repo } = readyToRelease();
    try {
      // A rehearsal that passes where the real run would fail is not a rehearsal. That is the
      // exact trap #1201 recorded, and re-creating it one command along would be careless.
      await assert.rejects(
        () => prepareRelease('0.6.0', { root: repo.dir, yes: true, dryRun: true }),
        /refusing to prepare a release on main/,
      );
    } finally {
      repo.cleanup();
    }
  });

  test('prepare commits on the branch and pushes and tags NOTHING', async () => {
    const { repo, remote } = readyToRelease();
    try {
      const mainBefore = repo.git('rev-parse main').trim();
      const remoteBefore = remote.refs();
      repo.git('checkout -q -b main_chore_release_0.6.0');

      await prepareRelease('0.6.0', { root: repo.dir, yes: true });

      assert.match(readFileSync(join(repo.dir, 'CHANGELOG.md'), 'utf8'), /## v0\.6\.0/, 'it wrote the notes');
      assert.match(repo.git('log -1 --pretty=%s').trim(), /^chore\(release\): v0\.6\.0$/, 'and committed them');
      assert.equal(repo.git('status --porcelain').trim(), '', 'leaving a clean tree');

      assert.equal(repo.git('tag -l v0.6.0').trim(), '', 'no tag — tagging is the other command');
      assert.equal(repo.git('rev-parse main').trim(), mainBefore, 'and main did not move');
      assert.deepEqual(remote.refs(), remoteBefore, 'nothing reached origin at all');
    } finally {
      repo.cleanup();
    }
  });

  test('tag refuses anywhere but main', async () => {
    const { repo } = readyToRelease();
    try {
      repo.git('checkout -q -b main_chore_release_0.6.0');
      await prepareRelease('0.6.0', { root: repo.dir, yes: true });

      // The notes exist and the tree is clean — every other guard passes. Only the branch is
      // wrong, which is the case where tagging would publish an unreviewed commit.
      await assert.rejects(
        () => tagRelease('0.6.0', { root: repo.dir, yes: true }),
        /refusing to tag from main_chore_release_0\.6\.0/,
      );
    } finally {
      repo.cleanup();
    }
  });

  test('tag refuses a version CHANGELOG.md has no section for', async () => {
    const { repo } = readyToRelease();
    try {
      // On main, clean tree, manifest matching, no such tag — everything preflight asks for.
      // The one thing missing is the prepare PR, which is precisely what the split makes
      // possible to forget, and what the old welded command made impossible to.
      await assert.rejects(
        () => tagRelease('0.6.0', { root: repo.dir, yes: true }),
        /CHANGELOG\.md has no section for v0\.6\.0/,
      );
      assert.equal(repo.git('tag -l v0.6.0').trim(), '', 'and it did not tag anyway');
    } finally {
      repo.cleanup();
    }
  });

  test('tag refuses when local main is behind or ahead of origin/main', async () => {
    const { repo } = readyToRelease();
    try {
      repo.git('checkout -q -b main_chore_release_0.6.0');
      await prepareRelease('0.6.0', { root: repo.dir, yes: true });
      // The prepare PR "merged" locally but never pushed. The old flow pushed main immediately
      // before tagging, so this could not happen; the split removes that push, and tagging a
      // commit nobody else has puts a tag on origin pointing into thin air.
      repo.git('checkout -q main');
      repo.git('merge -q --ff-only main_chore_release_0.6.0');

      await assert.rejects(
        () => tagRelease('0.6.0', { root: repo.dir, yes: true }),
        /main is not in step with origin\/main/,
      );
    } finally {
      repo.cleanup();
    }
  });

  test('tag pushes the tag and only the tag', async () => {
    const { repo, remote } = readyToRelease();
    try {
      repo.git('checkout -q -b main_chore_release_0.6.0');
      await prepareRelease('0.6.0', { root: repo.dir, yes: true });

      // Stand in for the reviewed PR being merged: main advances, and origin has it.
      repo.git('checkout -q main');
      repo.git('merge -q --ff-only main_chore_release_0.6.0');
      repo.git('push -q origin main');

      const before = remote.refs();
      await tagRelease('0.6.0', { root: repo.dir, yes: true });
      const after = remote.refs();

      assert.ok(after['refs/tags/v0.6.0'], 'the tag reached origin — that is what builds and submits');
      // WHAT THIS DOES AND DOES NOT PROVE, because an assertion trusted for more than it does is
      // worse than none. It catches tagRelease pushing any OTHER ref — verified by mutation, a
      // stray `push origin HEAD:refs/heads/stray` turns this red. It CANNOT catch someone adding
      // `git push origin main` back: the sync guard above means local main already equals
      // origin/main by the time we get here, so that push is "Everything up-to-date" and moves
      // nothing. That is not a hole in the test — it is the sync guard doing its job. The branch
      // push cannot matter, which is a stronger property than the code merely not attempting it.
      assert.deepEqual(
        Object.keys(after).filter((ref) => !(ref in before)),
        ['refs/tags/v0.6.0'],
        'and it is the only NEW ref tagRelease put on origin',
      );
      assert.equal(after['refs/heads/main'], before['refs/heads/main'], 'main was not moved');
      assert.equal(repo.git('status --porcelain').trim(), '', 'and nothing was written');
    } finally {
      repo.cleanup();
    }
  });

  test('tag refuses when main has moved on since the notes were written', async () => {
    const { repo } = readyToRelease();
    try {
      repo.git('checkout -q -b main_chore_release_1.0.2');
      await prepareRelease('0.6.0', { root: repo.dir, yes: true });
      repo.git('checkout -q main');
      repo.git('merge -q --ff-only main_chore_release_1.0.2');

      // Somebody else's PR lands during the review window. This repo has several agents merging
      // at once, so this is the normal case, not a contrived one. The old one-shot release could
      // not hit it: it generated the notes and tagged in a single execution.
      repo.mergePR(2, 'fix(www): a late unrelated change', 'www/pages/late.vue');
      repo.git('push -q origin main');

      // Every other guard passes: on main, clean, manifest matches, the section exists, and main
      // is in step with origin. Only the tag target is wrong — and tagging here would submit a
      // build containing PR #2 to a store whose changelog never mentions it, permanently.
      await assert.rejects(
        () => tagRelease('0.6.0', { root: repo.dir, yes: true }),
        /main has moved on since the v0\.6\.0 notes were written/,
      );
      assert.equal(repo.git('tag -l v0.6.0').trim(), '', 'and it did not tag anyway');
    } finally {
      repo.cleanup();
    }
  });

  test('tag accepts a prepare PR that landed as a merge commit, not only a fast-forward', async () => {
    const { repo, remote } = readyToRelease();
    try {
      repo.git('checkout -q -b main_chore_release_1.0.2');
      await prepareRelease('0.6.0', { root: repo.dir, yes: true });

      // A real merge commit, which is what GitHub produces on a merge-commit strategy. HEAD is
      // now the merge, not the commit that wrote the notes — and `git log -1 -- CHANGELOG.md`
      // applies history simplification, so it reports the branch commit. Comparing shas refused
      // this; comparing trees accepts it, because the content being tagged is identical.
      repo.git('checkout -q main');
      repo.git('merge -q --no-ff main_chore_release_1.0.2 -m "Merge pull request #9 from kimtos-labs/release"');
      repo.git('push -q origin main');
      assert.notEqual(
        repo.git('log -1 --format=%H -- CHANGELOG.md').trim(),
        repo.git('rev-parse HEAD').trim(),
        'the fixture must actually exercise the sha-mismatch case, or this test proves nothing',
      );

      const before = remote.refs();
      await tagRelease('0.6.0', { root: repo.dir, yes: true });
      assert.deepEqual(
        Object.keys(remote.refs()).filter((ref) => !(ref in before)),
        ['refs/tags/v0.6.0'],
        'a merge-committed prepare PR must still be taggable',
      );
    } finally {
      repo.cleanup();
    }
  });

  test('prepare refuses a version the changelog already covers, before writing anything', async () => {
    const { repo } = readyToRelease();
    try {
      repo.git('checkout -q -b main_chore_release_1.0.2');
      await prepareRelease('0.6.0', { root: repo.dir, yes: true });
      // Land it, then try to prepare the same version again — which is exactly what tagRelease
      // tells you to do when main has moved on, so this path is reached by instruction.
      repo.git('checkout -q main');
      repo.git('merge -q --ff-only main_chore_release_1.0.2');
      repo.git('checkout -q -b main_chore_release_1.0.2_again');

      await assert.rejects(
        () => prepareRelease('0.6.0', { root: repo.dir, yes: true }),
        /CHANGELOG\.md already has a v0\.6\.0 section/,
      );
      // The point of the guard is WHERE it fires. `addRelease` has always thrown on a duplicate,
      // but only after every touched unit's changelog and package.json had been rewritten — a
      // dirty tree with partial writes and nothing committed.
      assert.equal(repo.git('status --porcelain').trim(), '', 'nothing may have been written');
    } finally {
      repo.cleanup();
    }
  });

  test('tag reports the wrong branch before it reports a dirty tree', async () => {
    const { repo } = readyToRelease();
    try {
      repo.git('checkout -q -b main_chore_release_1.0.2');
      writeFileSync(join(repo.dir, 'scratch.txt'), 'uncommitted');

      // Both are wrong at once. The branch is the structural mistake, so it is the one to say —
      // reporting the tree first sends the user to clean it up and only then tells them the real
      // problem. prepareRelease already orders it this way; the two must agree.
      await assert.rejects(
        () => tagRelease('0.6.0', { root: repo.dir, yes: true }),
        /refusing to tag from main_chore_release_1\.0\.2/,
      );
    } finally {
      repo.cleanup();
    }
  });

  test('the old one-shot release() is gone, and says what replaced it', () => {
    // It is exported API of this package. Someone running it from muscle memory deserves the
    // two commands, not "not a function".
    assert.throws(() => release(), /make release-prepare[\s\S]*make release-tag/);
  });
});
